INSERT OR REPLACE INTO daiun_texts (kanshi,gogyo,theme,description,love,work,advice) VALUES
('己丑','土','この時期の運気','この10年は己丑の気を持つ時期です。土の性質が強まり、あなたの中にある土の力が最も輝きます。この時期の流れに乗ることで、次のステージへの大きな力が育まれます。焦らず、この時期にしかできない経験を大切にしてください。','この時期は縁が豊かになりやすく、誠実に向き合うことで長く続く大切な関係が育まれます。','この時期の特性を活かした仕事で力を発揮できます。自分らしく取り組むことが最大の成果につながります。','この時期の流れを信じてください。あなたのペースで着実に進むことが、最善の道です。');